count1, count2 = frequency arrays for word1, word2
d1, d2 = number of nonzero entries in count1, count2
for c1 in 0..25 where count1[c1] > 0:
    for c2 in 0..25 where count2[c2] > 0:
        if c1 == c2:
            if d1 == d2: return true
        else:
            nd1 = d1 - (1 if count1[c1]==1 else 0) + (1 if count1[c2]==0 else 0)
            nd2 = d2 - (1 if count2[c2]==1 else 0) + (1 if count2[c1]==0 else 0)
            if nd1 == nd2: return true
return false
